-- 智学领航 · 演示数据（全部为构造数据，不是真实试用结果）
-- 覆盖：12 名学生、189 条练习（180 条常规 + 9 条到期复习）、错题本、三层推荐、今日/昨日计划明细、12 条讲解留痕、画像快照。
-- 标注：姓名前缀“演示学生”，班级“演示数据-*”，作答/错题/讲解/推荐正文均带“[演示数据]”。
-- 幂等：练习/错题/计划/推荐/快照按固定键 upsert；讲解留痕按 explain_id 判重。
USE zhixue;
SET NAMES utf8mb4;

-- 12 名学生 × 5 个知识点 × 3 次练习 = 180 条；低/中/高三种画像。
-- 到期复习种子：3 名学生各 2 个知识点，距上次答对 40 天、距上次练习 40—46 天（≥30 天半衰 + ≥7 天冷却）。
-- 每题样本 1—2 次（低于画像 min-samples=3），不会挤进“5 个薄弱点”；选题均不在今日计划（Q_0201/Q_0203/Q_0302）。
(2, 'demo-prac-due-2-1', 'Q_0218', 'KP0202', 'SELF', 0, '[演示数据] 到期复习种子：基数算错', 'CALCULATION_ERROR', 62, DATE_SUB(NOW(), INTERVAL 46 DAY)),
(2, 'demo-prac-due-2-2', 'Q_0219', 'KP0202', 'SELF', 1, '[演示数据] 到期复习种子：概念链复述', NULL, 58, DATE_SUB(NOW(), INTERVAL 40 DAY)),
(2, 'demo-prac-due-2-3', 'Q_0311', 'KP0303', 'SELF', 1, '[演示数据] 到期复习种子：聚合查询', NULL, 51, DATE_SUB(NOW(), INTERVAL 40 DAY)),
(9001, 'demo-prac-due-9001-1', 'Q_0225', 'KP0202', 'SELF', 0, '[演示数据] 到期复习种子：笛卡儿积应用边界', 'CONCEPT_CONFUSION', 74, DATE_SUB(NOW(), INTERVAL 46 DAY)),
(9001, 'demo-prac-due-9001-2', 'Q_0219', 'KP0202', 'SELF', 1, '[演示数据] 到期复习种子：概念链复述', NULL, 63, DATE_SUB(NOW(), INTERVAL 40 DAY)),
(9001, 'demo-prac-due-9001-3', 'Q_0205', 'KP0205', 'SELF', 1, '[演示数据] 到期复习种子：关系代数', NULL, 52, DATE_SUB(NOW(), INTERVAL 40 DAY)),
(9004, 'demo-prac-due-9004-1', 'Q_0213', 'KP0201', 'SELF', 0, '[演示数据] 到期复习种子：关系模型概念混淆', 'CONCEPT_CONFUSION', 66, DATE_SUB(NOW(), INTERVAL 46 DAY)),
(9004, 'demo-prac-due-9004-2', 'Q_0213', 'KP0201', 'SELF', 1, '[演示数据] 到期复习种子：关系模型概念复述', NULL, 55, DATE_SUB(NOW(), INTERVAL 40 DAY)),
(9004, 'demo-prac-due-9004-3', 'Q_0205', 'KP0205', 'SELF', 1, '[演示数据] 到期复习种子：关系代数', NULL, 48, DATE_SUB(NOW(), INTERVAL 40 DAY))
ON DUPLICATE KEY UPDATE q_id = VALUES(q_id), kp_id = VALUES(kp_id), source = VALUES(source), is_correct = VALUES(is_correct), my_answer = VALUES(my_answer), error_type = VALUES(error_type), cost_seconds = VALUES(cost_seconds), created_at = VALUES(created_at);

-- 每个学生的薄弱知识点都有一条已确认错题，保证画像薄弱点能点进错题本。
ON DUPLICATE KEY UPDATE q_id = VALUES(q_id), kp_id = VALUES(kp_id), ocr_confidence = VALUES(ocr_confidence), error_type = VALUES(error_type), student_note = VALUES(student_note), status = VALUES(status), confirmed_at = VALUES(confirmed_at), created_at = VALUES(created_at);

-- 每人 3 条三层推荐，关联最新错题 log_id 与真实题号。
ON DUPLICATE KEY UPDATE layer = VALUES(layer), reason = VALUES(reason), rank_no = VALUES(rank_no), is_adopted = VALUES(is_adopted), created_at = VALUES(created_at);

-- 今日/昨日计划主表；done_count 稍后按明细重算。
ON DUPLICATE KEY UPDATE plan_count = VALUES(plan_count), done_count = VALUES(done_count), status = VALUES(status);

-- 今日/昨日计划各 3 条明细：今日 2 做 1 未做，昨日全做；随后重算 done_count。
ON DUPLICATE KEY UPDATE q_id = VALUES(q_id), kp_id = VALUES(kp_id), sort_no = VALUES(sort_no), is_done = VALUES(is_done), practice_id = VALUES(practice_id);

UPDATE study_plan p SET p.done_count = (SELECT COUNT(*) FROM study_plan_item i WHERE i.plan_id = p.plan_id AND i.is_done = 1), p.status = CASE WHEN (SELECT COUNT(*) FROM study_plan_item i WHERE i.plan_id = p.plan_id AND i.is_done = 1) >= p.plan_count THEN 'DONE' ELSE 'PENDING' END WHERE p.user_id IN (2,9001,9002,9003,9004,9005,9006,9007,9008,9009,9010,9011);

-- 每人 2 条画像快照（7 天前 + 今日）；student01 旧快照更低，形成“低→回升”。
ON DUPLICATE KEY UPDATE dimension_scores = VALUES(dimension_scores), weakest_kps = VALUES(weakest_kps), error_dist = VALUES(error_dist), total_practice = VALUES(total_practice), total_error = VALUES(total_error);

-- 12 条 RAG 讲解留痕：9 条待评阅、3 条已评阅；覆盖不同 KP/题型/错因。
SELECT 'DEMO_EX_EL_DEMO_2_1', 'DEMO_TRACE_EL_DEMO_2_1', 2, 'EL_DEMO_2_1', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1270, 620, 380, JSON_ARRAY('KP0201'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0201（单选，错因：概念混淆）。本题考关系模型的基本概念，抓的是“关系”和“二维表”的边界：关系模型由关系数据结构、关系操作集合、关系完整性约束三部分组成，二维表只是关系数据结构的直观表示，不能反过来说“关系就是表”。常见错选把“表名加列名”的形式直接当成关系模型本身，或把实体之间的联系误当作关系操作。讲解顺序：先回到三要素，再逐项检查选项有没有偷换概念。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 5 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_2_1');

SELECT 'DEMO_EX_EL_DEMO_9001_3', 'DEMO_TRACE_EL_DEMO_9001_3', 9001, 'EL_DEMO_9001_3', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1340, 620, 380, JSON_ARRAY('KP0302'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0302（单选，错因：计算失误/操作粒度判断错）。本题区分 DROP TABLE 与 DELETE FROM：删除表中已有数据、保留表结构，应使用 DELETE FROM 表名（教材口径也可用 TRUNCATE TABLE 清空）；DROP TABLE 会把表定义一起删除。错选 DROP 是把“清空数据”和“删表”两个粒度混在一起。讲解先问“删的是数据还是表定义”，再对应语句。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 4 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9001_3');

SELECT 'DEMO_EX_EL_DEMO_9002_4', 'DEMO_TRACE_EL_DEMO_9002_4', 9002, 'EL_DEMO_9002_4', 'RAG', 'local-template', 'demo-v1', 1, 'L3', 45, 0, 0, JSON_ARRAY('KP0305'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0307（单选，错因：步骤遗漏）。本题考嵌套查询的写法约束：子查询要用括号括起，子查询的 SELECT 子句不能写 ORDER BY（教材口径），相关子查询要随着外层元组逐行求值。常见错选漏掉“相关子查询逐行求值”这一步，或忽略子查询的位置与括号要求。讲解按“父查询—子查询—相关条件”三步核对，指出漏在哪一步。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 3 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9002_4');

SELECT 'DEMO_EX_EL_DEMO_9003_6', 'DEMO_TRACE_EL_DEMO_9003_6', 9003, 'EL_DEMO_9003_6', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1480, 620, 380, JSON_ARRAY('KP0203'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0220（简答，错因：边界条件）。本题的边界在“最小性”和“全码”：候选码要能唯一标识元组且真子集不能再唯一标识；主码是选定的一个候选码；包含在任一候选码中的属性是主属性，其余是非主属性；全部属性组成的候选码才是全码。常见错答把“能唯一标识”当成充分条件而漏掉最小性，或把全码这一极端情形漏掉。讲解按定义链逐项对照。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 6 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9003_6');

SELECT 'DEMO_EX_EL_DEMO_9004_6', 'DEMO_TRACE_EL_DEMO_9004_6', 9004, 'EL_DEMO_9004_6', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1550, 620, 380, JSON_ARRAY('KP0202'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0218（填空，错因：计算失误）。本题算笛卡儿积的基数：若各域基数为 m1 到 mn，则 D1×D2×…×Dn 的基数是 m1×m2×…×mn，是连乘不是相加；任一域基数为 0 时结果基数也为 0。常见错填写成各基数之和，或漏乘其中一项。讲解先把每个域的基数写出来，再逐项相乘，最后核对因子个数一个不少。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 7 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9004_6');

SELECT 'DEMO_EX_EL_DEMO_9005_6', 'DEMO_TRACE_EL_DEMO_9005_6', 9005, 'EL_DEMO_9005_6', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1620, 620, 380, JSON_ARRAY('KP0202'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0219（简答，错因：概念链混淆导致判断错）。本题要把域、笛卡儿积、关系、元组、属性串成一条链：域是属性取值的集合；笛卡儿积是所有可能组合的集合；关系是笛卡儿积的子集；元组是关系中的一行，也是笛卡儿积的一个元素；属性是关系中的一列。常见错答把“笛卡儿积的全体元素”直接等同于关系，或把元组和属性的角色对调。讲解就按这条链逐项说。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 8 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9005_6');

SELECT 'DEMO_EX_EL_DEMO_9006_6', 'DEMO_TRACE_EL_DEMO_9006_6', 9006, 'EL_DEMO_9006_6', 'RAG', 'local-template', 'demo-v1', 1, 'L3', 45, 0, 0, JSON_ARRAY('KP0202'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0225（综合，错因：算完未处理应用边界）。第一步算基数：2×101×3=606；第二步回答能否直接当关系用：笛卡儿积给出的是所有组合，直接当关系还要满足属性语义、元组能表达现实联系，通常要取有意义的子集并定义候选码，否则会出现无意义组合。常见错答只算 606、不回答第二问。讲解分两步：先乘，再谈子集与码。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 9 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9006_6');

SELECT 'DEMO_EX_EL_DEMO_9007_2', 'DEMO_TRACE_EL_DEMO_9007_2', 9007, 'EL_DEMO_9007_2', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1760, 620, 380, JSON_ARRAY('KP0206'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0206（单选，错因：规则漏项）。本题考实体完整性：主码为（学号，课程号），因此学号和课程号都不能为空；成绩不是主码属性，按本表口径可以为空。常见错选漏掉“主码的每个属性都不能为空”，或把成绩也当成主码属性一起要求非空。讲解先圈出主码包含哪几列，再逐列判断是否允许为空。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 10 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9007_2');

SELECT 'DEMO_EX_EL_DEMO_9008_3', 'DEMO_TRACE_EL_DEMO_9008_3', 9008, 'EL_DEMO_9008_3', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1830, 620, 380, JSON_ARRAY('KP0107'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0118（多选，错因：概念混淆）。本题考三级模式结构：外模式是用户视图，模式是全局逻辑结构，内模式是物理存储结构；两级映像是外模式/模式映像和模式/内模式映像，分别支撑逻辑独立性与物理独立性。常见错选把“模式”当成物理存储，或把两级映像只记成一级。讲解按“三层加两映射”逐个核对选项。', 0, NULL, NULL, NULL, NULL, DATE_SUB(NOW(), INTERVAL 11 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9008_3');

SELECT 'DEMO_EX_EL_DEMO_9009_1', 'DEMO_TRACE_EL_DEMO_9009_1', 9009, 'EL_DEMO_9009_1', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 1900, 620, 380, JSON_ARRAY('KP0306'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0309（单选，错因：关键字口径混淆）。本题要求并操作保留重复元组，应使用 UNION ALL；UNION 会自动去重。错选 UNION 是把“去重”和“保留重复”两个口径弄反。讲解先问“要不要去重”，再选关键字；顺带提醒交和差操作对应的是 INTERSECT 与 EXCEPT。', 0, 3, '请补充连接条件的书写，并说明 UNION 与 UNION ALL 的差别。', 'RETURN', DATE_SUB(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 30 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9009_1');

SELECT 'DEMO_EX_EL_DEMO_9010_3', 'DEMO_TRACE_EL_DEMO_9010_3', 9010, 'EL_DEMO_9010_3', 'RAG', 'local-template', 'demo-v1', 1, 'L3', 45, 0, 0, JSON_ARRAY('KP0401'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0402（多选，错因：漏项）。本题列数据库安全威胁，常见来源包括非授权用户恶意存取与破坏、重要或敏感数据被泄露，以及内部人员误用、软硬件故障和自然灾害等。常见错选只勾“外部攻击”，漏掉内部与环境因素。讲解按“人—数据—环境”三类逐项过，避免漏选。', 0, 4, '[演示数据] 结构完整，建议补充一个反例。', 'PASS', DATE_SUB(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 31 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9010_3');

SELECT 'DEMO_EX_EL_DEMO_9011_3', 'DEMO_TRACE_EL_DEMO_9011_3', 9011, 'EL_DEMO_9011_3', 'RAG', 'deepseek-chat', 'demo-v1', 0, NULL, 2040, 620, 380, JSON_ARRAY('KP0408'), '[演示数据] 本题讲解为演示用文本，不是真实 AI 输出。题号 Q_0419（综合，错因：授权粒度与边界）。本题的边界有三处：表级权限与列级权限（工资字段单独授权）不同；每个职工只对自己记录有 SELECT，必须用视图加谓词再授权，不能靠表级授权实现；“WITH GRANT OPTION”只影响转授权，不改变权限范围。常见错答把列级写成表级，或漏掉视图这一层。讲解按“对象—粒度—转授权”三问逐条核对。', 0, 4, '[演示数据] 结构完整，建议补充一个反例。', 'PASS', DATE_SUB(NOW(), INTERVAL 3 DAY), DATE_SUB(NOW(), INTERVAL 32 HOUR) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ai_generation_log WHERE explain_id = 'DEMO_EX_EL_DEMO_9011_3');
